  SALES_STOREID_STORE_STOREID AS SALES ("STOREID") REFERENCES STORE ("STOREID"),
  SALES_PRODUCTID_PRODUCT_PRODUCTID AS SALES ("PRODUCTID") REFERENCES PRODUCT ("PRODUCTID"),
  SALES_DATE_CALENDAR_DATE AS SALES ("COL_DATE") REFERENCES CALENDAR ("COL_DATE"),
  CUSTOMER_ID_SALES_ID AS CUSTOMER ("ID") REFERENCES SALES ("ID"),
