  CALENDAR."WIF_FORECAST_DEN" AS COUNT(*),
  CALENDAR."WIF_FORECAST_NUM" AS SUM(CALENDAR.MONTH::FLOAT),
  SALES."RETURN_RATE_DEN" AS SUM(SALES.AMOUNT::FLOAT),
  SALES."RETURN_RATE_NUM" AS (SUM(CASE WHEN SALES.STATUS = 'Returned' THEN SALES.AMOUNT ELSE 0 END::FLOAT)),
  PCT_RETURN_RATE."PCT_RETURN_RATE_VALUE" AS IFF(COUNT(DISTINCT PCT_RETURN_RATE.PCT_RETURN_RATE) + MAX(IFF(PCT_RETURN_RATE.PCT_RETURN_RATE IS NULL, 1, 0)) = 1, MAX(PCT_RETURN_RATE.PCT_RETURN_RATE), NULL) / NULLIF(100, 0),
  DETAILS."INFO_TOOLTIP" AS CAST(NULL AS DOUBLE) COMMENT = 'expression has no column/measure/table reference (a compile-time constant) — there is nothing to aggregate, so this is not a DAX translation failure.',
  DETAILS."INFO_TOOLTIP_2" AS CAST(NULL AS DOUBLE) COMMENT = 'expression has no column/measure/table reference (a compile-time constant) — there is nothing to aggregate, so this is not a DAX translation failure.',
  SALES."NET_SALES" AS SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT),
  SALES."NET_SALES_PM" AS SUM(CASE WHEN SALES.IS_SPLY_MONTH THEN CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END ELSE NULL END::FLOAT),
  SALES."LAST_2_MONTHS_NET_SALES" AS (SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT)) + (SUM(CASE WHEN SALES.IS_SPLY_MONTH THEN CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END ELSE NULL END::FLOAT)),
  SALES."NET_SALES_VARIANCE" AS (SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT)) - (SUM(CASE WHEN SALES.IS_SPLY_MONTH THEN CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END ELSE NULL END::FLOAT)),
  SALES."NET_SALES_VARIANCE_PCT" AS IFF(COALESCE((SUM(CASE WHEN SALES.IS_SPLY_MONTH THEN CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END ELSE NULL END::FLOAT)), 0) = 0, 0, (SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT)) / (SUM(CASE WHEN SALES.IS_SPLY_MONTH THEN CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END ELSE NULL END::FLOAT))) - 1,
