  SALES."RETURNS_PM" AS SUM(CASE WHEN SALES.IS_SPLY_MONTH THEN CASE WHEN SALES.STATUS = 'Returned' THEN SALES.AMOUNT ELSE 0 END ELSE NULL END::FLOAT),
  SALES."LAST_2_MONTHS_RETURNS" AS (SUM(CASE WHEN SALES.STATUS = 'Returned' THEN SALES.AMOUNT ELSE 0 END::FLOAT)) + (SUM(CASE WHEN SALES.IS_SPLY_MONTH THEN CASE WHEN SALES.STATUS = 'Returned' THEN SALES.AMOUNT ELSE 0 END ELSE NULL END::FLOAT)),
  SALES."RETURNS_VARIANCE" AS (SUM(CASE WHEN SALES.STATUS = 'Returned' THEN SALES.AMOUNT ELSE 0 END::FLOAT)) - (SUM(CASE WHEN SALES.IS_SPLY_MONTH THEN CASE WHEN SALES.STATUS = 'Returned' THEN SALES.AMOUNT ELSE 0 END ELSE NULL END::FLOAT)),
