  SALES."UNITS_RETURNED" AS SUM(CASE WHEN SALES.STATUS = 'Returned' THEN SALES.UNIT ELSE 0 END::FLOAT),
  SALES."UNITS_RETURNED_PM" AS SUM(CASE WHEN SALES.IS_SPLY_MONTH THEN CASE WHEN SALES.STATUS = 'Returned' THEN SALES.UNIT ELSE 0 END ELSE NULL END::FLOAT),
  SALES."UNITS_RETURNED_VARIANCE_PCT" AS IFF(COALESCE((SUM(CASE WHEN SALES.IS_SPLY_MONTH THEN CASE WHEN SALES.STATUS = 'Returned' THEN SALES.UNIT ELSE 0 END ELSE NULL END::FLOAT)), 0) = 0, 0, (SUM(CASE WHEN SALES.STATUS = 'Returned' THEN SALES.UNIT ELSE 0 END::FLOAT)) / (SUM(CASE WHEN SALES.IS_SPLY_MONTH THEN CASE WHEN SALES.STATUS = 'Returned' THEN SALES.UNIT ELSE 0 END ELSE NULL END::FLOAT))) - 1,
  CUSTOMER."RETURN_RATE" AS IFF(COALESCE(100, 0) = 0, 0, ROUND(IFF(COALESCE(SUM(CUSTOMER."SALES_AMOUNT"::FLOAT), 0) = 0, 0, (SUM(CASE WHEN SALES.STATUS = 'Returned' THEN SALES.AMOUNT ELSE 0 END::FLOAT)) / SUM(CUSTOMER."SALES_AMOUNT"::FLOAT)) * 100, 0) / 100),
  CUSTOMER."WIF_UNITS_RETURNED" AS CAST(NULL AS DOUBLE),
