  CUSTOMER."WIF_UNITS_RETURNED_DIFFERENCE" AS CAST(NULL AS DOUBLE),
  SALES."WIF_UNITS_RETURNED_1" AS CAST(NULL AS DOUBLE) COMMENT = 'not applicable: depends on report selection (ALLSELECTED)',
  CUSTOMER."WIF_UNITS_RETURNED_2" AS CAST(NULL AS DOUBLE) COMMENT = 'not applicable: depends on report selection (ALLSELECTED)',
  CUSTOMER."WIF_ADJUSTED_UNITS_RETURNED" AS CAST(NULL AS DOUBLE) COMMENT = 'Unsupported (disconnected polymorphic selector): metric references table alias(es) PCT_RETURN_RATE that are not reachable from its anchor table entity ''CUSTOMER'' via declared relationships.',
  SALES."WIF_ADJUSTED_NET_SALES" AS SUM(SALES.UNIT::FLOAT) * (IFF(COALESCE(SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT), 0) = 0, 0, SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT) / SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT))) - IFF(COALESCE(1, 0) = 0, 0, SUM(SALES.UNIT::FLOAT) * (0) / 1) * (IFF(COALESCE(SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT), 0) = 0, 0, SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT) / SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT))),
  SALES."WIF_PRICE_PER_UNIT" AS IFF(COALESCE(SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT), 0) = 0, 0, SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT) / SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT)),
