(COALESCE(SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT), 0) = 0, 0, SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT) / SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT)))) - (SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT))) * FLOOR(ABS((SUM(SALES.UNIT::FLOAT) * (IFF(COALESCE(SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT), 0) = 0, 0, SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT) / SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT))) - IFF(COALESCE(1, 0) = 0, 0, SUM(SALES.UNIT::FLOAT) * (0) / 1) * (IFF(COALESCE(SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT), 0) = 0, 0, SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT) / SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT)))) - (SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT))), 0) END END COMMENT = 'Window metric over SALES.WIF_PROFIT. Must be queried with STORE."TYPE", STORE."STORE".',
