  SALES."WIF_SALES" AS SUM(SALES."NET_SALES"::FLOAT) OVER (PARTITION BY EXCLUDING CALENDAR."MONTH") COMMENT = 'Window metric over SALES.WIF_SALES. Must be queried with CALENDAR."MONTH".',
