  SALES."WIF_FORECAST" AS (SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT)) + (CASE WHEN (CASE WHEN (0) >= SUM(SALES."RETURN_RATE_NUM"::FLOAT) OVER (PARTITION BY EXCLUDING STORE."TYPE", STORE."STORE") / NULLIF(SUM(SALES."RETURN_RATE_DEN"::FLOAT) OVER (PARTITION BY EXCLUDING STORE."TYPE", STORE."STORE"), 0) THEN 0 ELSE 1 END) = 0 THEN 0 ELSE CASE WHEN SIGN((SUM(SALES.UNIT::FLOAT) * (IFF(COALESCE(SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT), 0) = 0, 0, SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT) / SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT))) - IFF(COALESCE(1, 0) = 0, 0, SUM(SALES.UNIT::FLOAT) * (0) / 1) * (IFF(COALESCE(SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT), 0) = 0, 0, SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT) / SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT)))) - (SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT))) * FLOOR(ABS((SUM(SALES.UNIT::FLOAT) * (IFF(COALESCE(SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT), 0) = 0, 0, SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT) / SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT))) - IFF(COALESCE(1, 0) = 0, 0, SUM(SALES.UNIT::FLOAT) * (0) / 1) * (IFF(COALESCE(SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT), 0) = 0, 0, SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT) / SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT)))) - (SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT))), 0) < 0 THEN 0 ELSE SIGN((SUM(SALES.UNIT::FLOAT) * (IFF(COALESCE(SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END::FLOAT), 0) = 0, 0, SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.AMOUNT ELSE 0 END::FLOAT) / SUM(CASE WHEN SALES.STATUS = 'Sold' THEN SALES.UNIT ELSE 0 END